def test_types(create_pg):
    """Complex datatypes round-trip through logical replication (insert/update/delete)."""
    publisher = create_pg("publisher", allows_streaming="logical")
    subscriber = create_pg("subscriber")

    publisher.safe_psql(_DDL)
    subscriber.safe_psql(_DDL)

    connstr = publisher.connstr() + " dbname=postgres"
    publisher.safe_psql("CREATE PUBLICATION tap_pub FOR ALL TABLES")
    subscriber.safe_psql(
        "CREATE SUBSCRIPTION tap_sub CONNECTION '{}' PUBLICATION tap_pub "
        "WITH (slot_name = tap_sub_slot)".format(connstr)
    )
    subscriber.wait_for_subscription_sync(publisher, "tap_sub")

    publisher.safe_psql(_INSERT)
    publisher.wait_for_catchup("tap_sub")
    assert (
        subscriber.safe_psql(_SELECT) == _EXPECTED_INSERT
    ), "check replicated inserts on subscriber"

    publisher.safe_psql(_UPDATE)
    publisher.wait_for_catchup("tap_sub")
    assert (
        subscriber.safe_psql(_SELECT) == _EXPECTED_UPDATE
    ), "check replicated updates on subscriber"

    publisher.safe_psql(_DELETE)
    publisher.wait_for_catchup("tap_sub")
    assert (
        subscriber.safe_psql(_SELECT) == _EXPECTED_DELETE
    ), "check replicated deletes on subscriber"

    # A domain with a SQL-language constraint needs an active snapshot to apply.
    publisher.safe_psql("INSERT INTO tst_dom_constr VALUES (11)")
    publisher.wait_for_catchup("tap_sub")
    assert (
        subscriber.safe_psql("SELECT sum(a) FROM tst_dom_constr") == "21"
    ), "sql-function constraint on domain"

    subscriber.stop("fast")
    publisher.stop("fast")
